assignments.value:
={{ $json.emails.map((e, i) => `=== EMAIL ${i + 1} ===
SUJET: ${(e.Subject || '').replace(/^(\s*(Fwd?|Re|TR|Fw)\s*:\s*)+/gi, '').trim()}
DE: ${e.From || ''}
DATE: ${DateTime.fromMillis(Number(e.internalDate)).toFormat('dd/MM/yyyy')}
LIEN: https://mail.google.com/mail/u/0/#inbox/${e.id || ''}
CONTENU:
${e.text || e.body || e.snippet || ''}
`).join('\n') }}
